public sealed class PayrollService
{
    private readonly IClockEntryRepository _clockEntryRepository;

    public PayrollService(IClockEntryRepository clockEntryRepository)
    {
        _clockEntryRepository = clockEntryRepository;
    }

    public double CalculateTotalHours(int employeeId, DateTime startDate, DateTime endDate)
    {
        IEnumerable<ClockEntry> entries = _clockEntryRepository.GetEmployeeClockEntries(employeeId, startDate, endDate);
        return entries.Sum(entry => entry.GetDuration()?.TotalHours ?? 0);
    }
}

public static class ClockEntryQueries
{
    public static IEnumerable<ClockEntry> CompletedNewestFirst(IEnumerable<ClockEntry> entries)
    {
        IEnumerable<ClockEntry> completedEntries = entries.Where(entry => entry.Clockout is not null);
        IEnumerable<ClockEntry> orderedEntries = completedEntries.OrderByDescending(entry => entry.ClockIn);
        return orderedEntries;
    }
}
